choose.when:
SELECT A.ITEMCD, A.ITSIZE, A.UNIT, A.ITEMNM, A.ITEMENM, A.INUNIT, A.INUNITNM,A.ICQTY,A.OUTUNIT,A.OUTUNITNM, A.OCQTY, A.SETYN, A.ASTKIND,A.AGRPCD, B.AGRPNM, A.BGRPCD, B.BGRPNM, A.IMPRICE,A.OMPRICE,A.STOCK, A.QTYPNT, A.VATYN, A.SOTAXYN, A.REMARK, A.USEYN, A.AUTOYN, A.UDOGYN, A.BARCODE,A.HSCODE, A.IN_CUSTCD, C.CUSTNM AS IN_CUSTNM FROM HSBA010T_TBL A LEFT OUTER JOIN HSBA030T_TBL B ON A.CMPYCD = B.CMPYCD AND A.ASTKIND = B.ASTKIND AND A.AGRPCD = B.AGRPCD AND A.BGRPCD = B.BGRPCD LEFT OUTER JOIN HABA020T_TBL C ON A.CMPYCD = C.CMPYCD AND A.IN_CUSTCD = C.CUSTCD WHERE A.CMPYCD = #{cmpycd} AND A.ASTKIND = #{astkind}
AND A.ITEMNM LIKE CONCAT('%', #{itemnm}, '%')
ORDER BY A.ITEMCD

SELECT A.CUSTCD, A.CUSTNO, A.CUSTNM, A.CUSTGBN, A.BOSSNM, A.JUMINNO, A.LEGALNO, A.CUSTKIND, A.CUSTTYPE, A.TELNO, A.FAXNO, A.POSTNO, A.ADDRESS, A.D_ADDRESS, A.IOGBN, J.CODENM AS IOGBNNM, IFNULL(B.INPRCGBN,'000') AS INPRCGBN, IFNULL(B.OUTPRCGBN,'000') AS OUTPRCGBN, IFNULL(B.HDAMT,0) AS HDAMT, IFNULL(B.RCVDD,0) AS RCVDD, IFNULL(B.AGRPCD,'000') AS AGRPCD, IFNULL(B.BGRPCD,'000') AS BGRPCD, IFNULL(B.CGRPCD,'000') AS CGRPCD, IFNULL(B.AREA,'000') AS AREA, B.DAMDANG AS CDAMDANG, B.TELNO AS CTELNO, B.EMAIL AS CEMAIL, B.REMARK, C.CDNM AS INPRCGBNM, D.CDNM AS OUTPRCGBNM, E.CDNM AS AGRPNM, F.CDNM AS BGRPNM , G.CDNM AS AREANM , A.STATUS, I.CODENM AS STATUSNM, A.USEYN, A.BANKNM, A.GUJOA, A.FNDYMD, A.STDYMD, A.CLSYMD, A.SINGRD, K.CODENM AS CUSTGBNM, A.ELCYN, A.GIGBCD, A.OUTCUSTCD FROM HABA020T_TBL A LEFT OUTER JOIN HSBA100T_TBL B ON A.CMPYCD = B.CMPYCD AND A.CUSTCD = B.CUSTCD LEFT OUTER JOIN HSBA900T_TBL C ON B.CMPYCD = C.CMPYCD AND B.INPRCGBN = C.CODE AND C.CDGBN = '200' LEFT OUTER JOIN HSBA900T_TBL D ON B.CMPYCD = D.CMPYCD AND B.OUTPRCGBN = D.CODE AND D.CDGBN = '200' LEFT OUTER JOIN HSBA900T_TBL E ON B.CMPYCD = E.CMPYCD AND B.AGRPCD = E.CODE AND E.CDGBN = '400' LEFT OUTER JOIN HSBA900T_TBL F ON B.CMPYCD = F.CMPYCD AND B.BGRPCD = F.CODE AND F.CDGBN = '410' LEFT OUTER JOIN HSBA900T_TBL G ON B.CMPYCD = G.CMPYCD AND B.AREA = G.CODE AND G.CDGBN = '430' LEFT OUTER JOIN HABA900T_TBL I ON A.STATUS = I.CODECD AND I.CDTYPE = '280' LEFT OUTER JOIN HABA900T_TBL J ON A.IOGBN = J.CODECD AND J.CDTYPE = '340' LEFT OUTER JOIN HABA900T_TBL K ON A.CUSTGBN = K.CODECD AND K.CDTYPE = '270' WHERE A.CMPYCD = #{cmpycd}
AND A.CUSTNM LIKE CONCAT('%', TRIM(#{custnm}), '%')
AND A.STATUS IN ('010','020','030') ORDER BY A.CUSTCD

choose.otherwise:
SELECT A.CUSTCD, A.CUSTNO, A.CUSTNM, A.CUSTGBN, A.BOSSNM, A.JUMINNO, A.LEGALNO, A.CUSTKIND, A.CUSTTYPE, A.TELNO, A.FAXNO, A.POSTNO, A.ADDRESS, A.D_ADDRESS, A.IOGBN, J.CODENM AS IOGBNNM, IFNULL(B.INPRCGBN,'000') AS INPRCGBN, IFNULL(B.OUTPRCGBN,'000') AS OUTPRCGBN, IFNULL(B.HDAMT,0) AS HDAMT, IFNULL(B.RCVDD,0) AS RCVDD, IFNULL(B.AGRPCD,'000') AS AGRPCD, IFNULL(B.BGRPCD,'000') AS BGRPCD, IFNULL(B.CGRPCD,'000') AS CGRPCD, IFNULL(B.AREA,'000') AS AREA, B.DAMDANG AS CDAMDANG, B.TELNO AS CTELNO, B.EMAIL AS CEMAIL, B.REMARK, C.CDNM AS INPRCGBNM, D.CDNM AS OUTPRCGBNM, E.CDNM AS AGRPNM, F.CDNM AS BGRPNM , G.CDNM AS AREANM , A.STATUS, I.CODENM AS STATUSNM, A.USEYN, A.BANKNM, A.GUJOA, A.FNDYMD, A.STDYMD, A.CLSYMD, A.SINGRD, K.CODENM AS CUSTGBNM, A.ELCYN, A.GIGBCD, A.OUTCUSTCD FROM HABA020T_TBL A LEFT OUTER JOIN HSBA100T_TBL B ON A.CMPYCD = B.CMPYCD AND A.CUSTCD = B.CUSTCD LEFT OUTER JOIN HSBA900T_TBL C ON B.CMPYCD = C.CMPYCD AND B.INPRCGBN = C.CODE AND C.CDGBN = '200' LEFT OUTER JOIN HSBA900T_TBL D ON B.CMPYCD = D.CMPYCD AND B.OUTPRCGBN = D.CODE AND D.CDGBN = '200' LEFT OUTER JOIN HSBA900T_TBL E ON B.CMPYCD = E.CMPYCD AND B.AGRPCD = E.CODE AND E.CDGBN = '400' LEFT OUTER JOIN HSBA900T_TBL F ON B.CMPYCD = F.CMPYCD AND B.BGRPCD = F.CODE AND F.CDGBN = '410' LEFT OUTER JOIN HSBA900T_TBL G ON B.CMPYCD = G.CMPYCD AND B.AREA = G.CODE AND G.CDGBN = '430' LEFT OUTER JOIN HABA900T_TBL I ON A.STATUS = I.CODECD AND I.CDTYPE = '280' LEFT OUTER JOIN HABA900T_TBL J ON A.IOGBN = J.CODECD AND J.CDTYPE = '340' LEFT OUTER JOIN HABA900T_TBL K ON A.CUSTGBN = K.CODECD AND K.CDTYPE = '270' WHERE A.CMPYCD = #{cmpycd}
AND A.CUSTNM LIKE CONCAT('%', TRIM(#{custnm}), '%')
AND A.STATUS IN ('010','020','030') AND A.CUSTGBN = #{custgbn} ORDER BY A.CUSTCD

choose.when:
UPDATE HABA020T_TBL SET CUSTNO = #{custno}, CUSTNM = #{custnm}, CUSTGBN = #{custgbn}, BOSSNM = #{bossnm}, LEGALNO = #{legalno}, CUSTKIND = #{custkind}, CUSTTYPE = #{custtype}, TELNO = #{telno}, FAXNO = #{faxno}, POSTNO = #{postno}, ADDRESS = #{address}, D_ADDRESS = #{d_address}, STATUS = #{status}, IOGBN = #{iogbn}, FNDYMD = #{fndymd}, STDYMD = #{stdymd}, CLSYMD = #{clsymd}, SINGRD = #{singrd}, ELCYN = #{elcyn}, USEYN = #{useyn}, BANKNM = #{banknm}, GUJOA = #{gujoa}, UPDTIME = NOW(), UPDEMP = #{updemp}, GIGBCD = #{gigbcd}, OUTCUSTCD = #{outcustcd} WHERE CMPYCD = #{cmpycd} AND CUSTCD = #{custcd};
INSERT INTO HSBA100T_TBL (CMPYCD, CUSTCD, INPRCGBN, OUTPRCGBN, HDAMT, RCVDD, AGRPCD, BGRPCD, CGRPCD, AREA, DAMDANG, TELNO, EMAIL, REMARK, USEYN, ADDTIME, UPDTIME, UPDEMP) VALUES (#{cmpycd}, #{custcd}, #{inprcgbn}, #{outprcgbn}, IFNULL(#{hdamt}, 0), IFNULL(#{rcvdd}, 0), #{agrpcd}, #{bgrpcd}, #{cgrpcd}, #{area}, #{cdamdang}, #{ctelno}, #{cemail}, #{remark}, #{useyn}, NOW(), NOW(), #{updemp}) ON DUPLICATE KEY UPDATE INPRCGBN = VALUES(INPRCGBN), OUTPRCGBN = VALUES(OUTPRCGBN), RCVDD = VALUES(RCVDD), AGRPCD = VALUES(AGRPCD), BGRPCD = VALUES(BGRPCD), CGRPCD = VALUES(CGRPCD), AREA = VALUES(AREA), DAMDANG = VALUES(DAMDANG), TELNO = VALUES(TELNO), EMAIL = VALUES(EMAIL), REMARK = VALUES(REMARK), USEYN = VALUES(USEYN), UPDTIME = NOW(), UPDEMP = VALUES(UPDEMP);
SELECT 'N' AS RESULT, '정상으로 작업이 되었습니다.' AS MSG;

INSERT INTO HABA020T_TBL (CMPYCD, CUSTCD, CUSTNO, CUSTNM, CUSTGBN, BOSSNM, JUMINNO, LEGALNO, CUSTKIND, CUSTTYPE, TELNO, FAXNO, POSTNO, ADDRESS, D_ADDRESS, IOGBN, FNDYMD, STDYMD, CLSYMD, SINGRD, STATUS, GUJOA, BANKNM, ELCYN, USEYN, ADDTIME, UPDTIME, UPDEMP, GIGBCD, OUTCUSTCD) VALUES (#{cmpycd}, COALESCE(NULLIF(#{custcd}, ''), CONCAT(#{custcd}, LPAD(IFNULL(MAX(CAST(x.CUSTCD AS UNSIGNED)), 0) + 2, 7, '0'))), #{custno}, #{custnm}, #{custgbn}, #{bossnm}, #{juminno}, #{legalno}, #{custkind}, #{custtype}, #{telno}, #{faxno}, #{postno}, #{address}, #{d_address}, #{iogbn}, #{fndymd}, #{stdymd}, #{clsymd}, #{singrd}, #{status}, #{gujoa}, #{banknm}, #{elcyn}, #{useyn}, NOW(), NOW(), #{updemp}, #{gigbcd}, #{outcustcd});
INSERT INTO HSBA100T_TBL (CMPYCD, CUSTCD, INPRCGBN, OUTPRCGBN, HDAMT, RCVDD, AGRPCD, BGRPCD, CGRPCD, AREA, DAMDANG, TELNO, EMAIL, REMARK, USEYN, ADDTIME, UPDTIME, UPDEMP) VALUES (#{cmpycd}, #{custcd}, #{inprcgbn}, #{outprcgbn}, IFNULL(#{hdamt}, 0), IFNULL(#{rcvdd}, 0), #{agrpcd}, #{bgrpcd}, #{cgrpcd}, #{area}, #{cdamdang}, #{ctelno}, #{cemail}, #{remark}, #{useyn}, NOW(), NOW(), #{updemp});
SELECT 'N' AS RESULT, '정상으로 작업이 되었습니다.' AS MSG;

SELECT CODE, CDNM, REMARK, DSPORD, USEYN
  FROM HSBA900T_TBL
 WHERE CMPYCD = #{cmpycd}
   AND CDGBN  = #{cdgbn}
 ORDER BY DSPORD

SELECT CODE, CDNM, REMARK, DSPORD, USEYN
  FROM HSBA900T_TBL
 WHERE CMPYCD = #{cmpycd}
   AND CDGBN  = #{cdgbn}
   AND USEYN  = 'Y'
 ORDER BY DSPORD

INSERT INTO HSBA900T_TBL (CMPYCD, CDGBN, CODE, CDNM, REMARK, DSPORD, USEYN, ADDTIME, UPDTIME, UPDEMP)
VALUES (#{cmpycd}, #{cdgbn}, #{code}, #{cdnm}, #{remark}, CAST(IFNULL(NULLIF(#{dspord}, ''), '0') AS SIGNED), #{useyn}, NOW(), NOW(), #{updemp})
ON DUPLICATE KEY UPDATE
CDNM = VALUES(CDNM), REMARK = VALUES(REMARK), DSPORD = VALUES(DSPORD), USEYN = VALUES(USEYN), UPDTIME = NOW(), UPDEMP = VALUES(UPDEMP);

SELECT 'OK' AS RESULT, '' AS MSG;

UPDATE HSBA900T_TBL
   SET CDNM    = #{cdnm},
       REMARK  = #{remark},
       DSPORD  = CAST(IFNULL(NULLIF(#{dspord}, ''), '0') AS SIGNED),
       USEYN   = #{useyn},
       UPDTIME = NOW(),
       UPDEMP  = #{updemp}
 WHERE CMPYCD    = #{cmpycd}
   AND CDGBN     = #{cdgbn}
   AND CODE      = #{code};

SELECT 'OK' AS RESULT, '' AS MSG;
